    const match = USES.exec(raw.replace(/\r$/, ''));
    if (!match) return;
    const rest = match[1]!.trim();
    const hash = rest.indexOf(' #');
    const action = (hash === -1 ? rest : rest.slice(0, hash)).trim();
    const comment = hash === -1 ? '' : rest.slice(hash + 1).trim();
